    else if(command.startsWith('flow-')){
      const op=command.slice(5);
      if(['load-comparison','load-comparison-report','load-comparison-csv','load-comparison-bundle'].includes(op)){
        if(!input)throw Error('Supply the original saved-load comparison selection with --file.');
        if(op==='load-comparison-bundle'&&!options.output)throw Error('A complete load-comparison ZIP requires --output FILE.zip.');
