        target = self.directory / "reaches.json"
        if target.exists() and target.read_bytes() == encoded:
            return
        temp = target.with_suffix(".pending")
        with temp.open("wb") as stream:
            stream.write(encoded); stream.flush(); os.fsync(stream.fileno())
