ce ./data --kind wqp|stations|usgs-daily --station USGS-... --from YYYY-MM-DD --to YYYY-MM-DD\nsummary|records|calibration|export|portable --workspace ./data --output result.json\nresult-source-selection --workspace ./data --id ORIGINAL_EXPORT_ID --output selection.json\nreceive --workspace ./empty-data --file complete-workspace.json\nmap --workspace ./data --station ORG-ID --reach r1 --reviewer Name --reason Rationale\nreview --workspace ./data --id HASH --state include|exclude|pending --reviewer Name --reason Rationale\nloads --workspace ./data --station ORG-ID --flow-station USGS-ID --parameter tn|tp --reason Rationale\n\nThe server also exposes the original-app integration API /api/measurement-workspace.\n`);
